{
  "items": [
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "LiouvilleWith.mono",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p q x : ℝ}, LiouvilleWith p x → q ≤ p → LiouvilleWith q x"
    },
    {
      "name": "LiouvilleWith.irrational",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ}, LiouvilleWith p x → 1 < p → Irrational x"
    },
    {
      "name": "Liouville",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "definition",
      "type": "ℝ → Prop"
    },
    {
      "name": "ae_not_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "∀ᵐ (x : ℝ), ∀ p > 2, ¬LiouvilleWith p x"
    },
    {
      "name": "Irreducible.degree_le_two",
      "module_name": "Mathlib.Analysis.Complex.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {p : Polynomial ℝ}, Irreducible p → p.degree ≤ 2"
    },
    {
      "name": "forall_liouvilleWith_iff",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, (∀ (p : ℝ), LiouvilleWith p x) ↔ Liouville x"
    },
    {
      "name": "volume_iUnion_setOf_liouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Measure",
      "kind": "theorem",
      "type": "MeasureTheory.volume (⋃ p, ⋃ (_ : 2 < p), {x | LiouvilleWith p x}) = 0"
    }
  ]
}
